import {locationExpiry} from './engine.js?v=186';
import {dataTable} from './data-tables.js?v=186';
import {ACTIONS,STAT_NAMES,COUNTRY,TECH} from './data.js?v=186';
import {esc,formatScore,portrait} from './ui.js?v=186';
const emptyRow=()=>({count:0,success:0,failed:0,stopped:0,cost:0,fatigue:0,exposure:0,chance:0,rolls:0,prestige:0});
function addResult(v,r){v.count++;v.success+=+(r.status==='RÉUSSITE');v.failed+=+(r.status==='ÉCHEC');v.stopped+=+(r.status==='INTERROMPUE');for(const key of ['cost','fatigue','exposure','prestige'])v[key]=(v[key]||0)+(r[key]||0);if(!ACTIONS[r.type].safe&&r.status!=='INTERROMPUE'&&Number.isFinite(r.chance)){v.rolls++;v.chance+=r.chance;}}
export function recordOperation(s,r){
 const stats=s.campaignStats??={partial:true,factions:{}},f=stats.factions[r.faction]??={},v=f[r.type]??=emptyRow();
 if(r.status==='RÉUSSITE'&&!ACTIONS[r.type].safe&&(r.type==='arrest'||r.chance<=50||r.type==='protect'))(stats.highlights??=[]).push({turn:r.turn,faction:r.faction,agent:r.agent,type:r.type,chance:r.chance});
 (stats.events??=[]).push({turn:r.turn,faction:r.faction,agentId:r.agentId||'',templateId:r.templateId||'',agent:r.agent,type:r.type,status:r.status,country:r.country||'',targetName:r.targetName||'',chance:r.chance??100,notes:(r.notes||[]).slice(0,8)});
 addResult(v,r);
 if(r.agentId){const roster=(stats.agents??={})[r.faction]??={},a=s.agents.find(a=>a.id===r.agentId),record=roster[r.agentId]??={name:r.agent,role:r.role||a?.role||'',templateId:r.templateId||a?.templateId||r.agentId,actions:{}};addResult(record.actions[r.type]??=emptyRow(),r);}
}
export function recordSupport(s,f,category,type,{cost=0,currency='credits',id=null,cancel=false,refund=0}={}){
 const stats=s.campaignStats??={partial:true,factions:{}},group=((stats.support??={})[f]??={})[category]??={},v=group[type]??={count:0,cancelled:0,cost:0,refund:0,currency};
 if(cancel){v.cancelled++;v.refund+=refund;}else{v.count++;v.cost+=cost;}
}
export function validateCampaignDetails(s,bad){
 const stats=s.campaignStats;stats.detailsPartial??=!stats.agents;stats.agents??={};stats.support??={};
 const object=v=>v&&typeof v==='object'&&!Array.isArray(v),text=v=>typeof v==='string'&&v.length<500&&!/[<>"]/.test(v),num=v=>Number.isFinite(v)&&Math.abs(v)<=1000000;
 if(stats.events!==undefined&&(!Array.isArray(stats.events)||stats.events.length>10000||stats.events.some(e=>!object(e)||!s.factions[e.faction]||!ACTIONS[e.type]||!Number.isInteger(e.turn)||e.turn<1||e.turn>40||!num(e.chance)||e.chance<0||e.chance>100||!['RÉUSSITE','ÉCHEC','INTERROMPUE'].includes(e.status)||['agent','agentId','templateId','country','targetName'].some(k=>!text(e[k]))||!Array.isArray(e.notes)||e.notes.length>8||e.notes.some(n=>typeof n!=='string'||n.length>5000))))bad();
 if(!object(stats.agents)||!object(stats.support)||typeof stats.detailsPartial!=='boolean')bad();
 for(const [f,agents] of Object.entries(stats.agents)){if(!s.factions[f]||!object(agents)||Object.keys(agents).length>150)bad();for(const [id,a] of Object.entries(agents)){if(!text(id)||!object(a)||!text(a.name)||!text(a.role)||!text(a.templateId)||!object(a.actions))bad();if(a.conditionHistory!==undefined&&(!Array.isArray(a.conditionHistory)||a.conditionHistory.length>41||a.conditionHistory.some((p,i,h)=>!object(p)||!Number.isInteger(p.turn)||p.turn<0||p.turn>40||i>0&&p.turn<=h[i-1].turn||!num(p.energy)||p.energy<0||p.energy>100||!num(p.exposure)||p.exposure<0||p.exposure>150||!['ready','injured','captured','dead','retired'].includes(p.status))))bad();for(const [k,v] of Object.entries(a.actions))if(!ACTIONS[k]||!object(v)||Object.keys(emptyRow()).some(n=>!num(v[n])))bad();}}
 for(const [f,groups] of Object.entries(stats.support)){if(!s.factions[f]||!object(groups))bad();for(const [category,rows] of Object.entries(groups)){if(!['operations','government'].includes(category)||!object(rows))bad();for(const [type,v] of Object.entries(rows)){if(!(category==='operations'?Object.hasOwn(TECH,type):['funding','medical','diplomacy','internal'].includes(type))||!object(v)||!['credits','confidence'].includes(v.currency)||['count','cancelled','cost','refund'].some(n=>!num(v[n])||v[n]<0))bad();}}}
}
export const AGENT_CATEGORIES=[['Déplacements',['travel','sneak']],['Enquête',['contacts','collect','analyze','surveil','prepare','counter']],['Intervention',['arrest','rescue','protect']],['Diplomatie',['authorize','influence','intimidate','blackmail']],['Appui numérique',['hack','drone','cyberSupport']],['Équipement et récupération',['equip','findSafehouse','fieldRest','hide','rest','heal']]];
function agentPanel(s,country){
 const records=s.campaignStats?.agents?.[country]||{},agents=new Map(s.agents.filter(a=>a.faction===country).map(a=>[a.id,{name:a.name,role:a.role,actions:{}}]));for(const [id,a] of Object.entries(records))agents.set(id,a);
 return `<h2>Agents · ${COUNTRY[country].name}</h2><p class="muted">Réussite = réussies / (réussies + échecs). Les interruptions sont séparées ; les actions automatiques ne gonflent pas le taux avec jet.</p><nav class="report-agent-tabs" aria-label="Choisir un agent">${[...agents].map(([id,a],i)=>`<button data-report-agent="${esc(id)}" aria-pressed="${i===0}">${esc(a.name)}</button>`).join('')}</nav><div class="report-agent-grid">${[...agents].map(([id,a],index)=>{const rows=Object.entries(a.actions),total=rows.reduce((n,[,v])=>n+v.count,0),rolled=rows.filter(([k])=>!ACTIONS[k].safe),wins=rolled.reduce((n,[,v])=>n+v.success,0),attempts=rolled.reduce((n,[,v])=>n+v.success+v.failed,0),cats=AGENT_CATEGORIES.map(([name,keys])=>({name,rows:rows.filter(([k])=>keys.includes(k))})),dominant=cats.filter(c=>!['Déplacements','Équipement et récupération'].includes(c.name)&&c.rows.length).sort((a,b)=>b.rows.reduce((n,[,v])=>n+v.count,0)-a.rows.reduce((n,[,v])=>n+v.count,0))[0];return `<article class="report-agent-card" data-agent-report="${esc(id)}" ${index?'hidden':''}><header><h3>${esc(a.name)}</h3><span>${esc(a.role)}</span></header><p><strong>${total}</strong> actions · <strong>${attempts?Math.round(wins/attempts*100)+' %':'—'}</strong> avec jet</p><p class="muted">Rôle observé : ${dominant?esc(dominant.name):total?'Déplacements et récupération':'Aucune action terminée'}</p>${cats.filter(c=>c.rows.length).map(c=>`<details open><summary>${esc(c.name)} · ${c.rows.reduce((n,[,v])=>n+v.count,0)} actions</summary>${dataTable(['Action','Total','Réussies','Échecs','Interrompues','Réussite'],c.rows.map(([k,v])=>[ACTIONS[k].name,v.count,v.success,v.failed,v.stopped,ACTIONS[k].safe?'Automatique':pct(rate(v))]))}</details>`).join('')}${agentConditionChart(s,country,id)}</article>`;}).join('')}</div>`;
}
function supportPanel(s,country){const labels={funding:'Financement exceptionnel',medical:'Soutien médical',diplomacy:'Démarche diplomatique',internal:'Influence interne'};return ['operations','government'].map(category=>{const rows=Object.entries(s.campaignStats?.support?.[country]?.[category]||{});return `<h2>${category==='operations'?'Modules d’opération':'Gouvernement'}</h2>${rows.length?dataTable(['Action','Activations','Annulations','Dépensé','Remboursé'],rows.map(([type,v])=>[TECH[type]?.name||labels[type],v.count,v.cancelled,v.cost+' '+(v.currency==='confidence'?'confiance':'crédits'),v.refund+' '+(v.currency==='confidence'?'confiance':'crédits')])):'<p class="muted">Aucune activation enregistrée.</p>'}`;}).join('');}
export function contributionBreakdown(s,faction){const result={protection:0,proofs:0,arrests:0,other:0,defended:0};for(const e of s.prestigeLedger||[]){if(e.faction!==faction)continue;const category=e.reason.startsWith('attentat déjoué')?'protection':e.key.startsWith('proof:')||e.reason.toLowerCase().includes('preuve')?'proofs':/arrestation|interpellation|localisation|préparation/i.test(e.reason)?'arrests':'other';result[category]+=e.points;if(category==='protection')result.defended++;}return result;}
export function investigationProgress(s,faction,t){const f=s.factions[faction],k=f?.known?.[t.id],proofs=(f?.evidence||[]).filter(e=>!e.contested&&s.proofs.some(p=>p.id===e.id&&p.suspect===t.id));const ownArrest=t.arrestedBy===faction;return [!!k&&!!f.access[t.country],proofs.length>=2,proofs.some(e=>e.verified),!!k?.prepared&&(locationExpiry(s,faction,t.id)>=s.turn||ownArrest),ownArrest].filter(Boolean).length*20;}
export function operationTotals(s,faction){const entries=Object.entries(s.campaignStats?.factions?.[faction]||{}).filter(([k])=>ACTIONS[k]),totals={count:0,success:0,failed:0,stopped:0,cost:0,rolls:0,chance:0,randomSuccess:0};for(const [k,v] of entries){for(const field of ['count','success','failed','stopped','cost','rolls','chance'])totals[field]+=v[field]||0;if(!ACTIONS[k].safe)totals.randomSuccess+=v.success;}return totals;}
const rate=v=>v.success+v.failed?Math.round(v.success/(v.success+v.failed)*100):null;
const pct=n=>n===null?'—':n+' %';
const cell=(text,value)=>({text,value:value??text});
const colors=['#e8b2c3','#9ac8d9','#d8bf89','#b9b4d7','#89baa3','#e39888'];
export function prestigeChart(s,factions){const ledger=s.prestigeLedger||[],max=Math.max(1,...factions.map(f=>f.score)),turns=Math.max(1,s.turn),x=t=>44+t/turns*690,y=n=>175-n/max*140;
 return `<figure class="report-chart"><figcaption>Évolution du prestige <small>Contributions enregistrées au fil des tours</small></figcaption><svg viewBox="0 0 770 210" role="img" aria-label="Évolution du prestige par pays, détaillée dans la chronologie"><path d="M44 25V175H734" class="chart-axis"/>${[0,.5,1].map(n=>`<g><path d="M44 ${y(n*max)}H734" class="chart-grid"/><text x="4" y="${y(n*max)+4}">${formatScore(n*max)}</text></g>`).join('')}${factions.map((f,i)=>{let total=ledger.filter(e=>e.faction===f.id&&e.turn===null).reduce((n,e)=>n+e.points,0),path=`M${x(0)} ${y(total)}`;for(let turn=1;turn<=turns;turn++){path+=` H${x(turn)}`;total+=ledger.filter(e=>e.faction===f.id&&e.turn===turn).reduce((n,e)=>n+e.points,0);path+=` V${y(total)}`;}return `<path d="${path}" fill="none" stroke="${colors[i%colors.length]}" stroke-width="2.5"><title>${esc(COUNTRY[f.id].name)} : ${formatScore(total)} points enregistrés</title></path>`;}).join('')}<text x="44" y="201">Départ</text><text x="692" y="201">Tour ${turns}</text></svg><div class="chart-legend">${factions.map((f,i)=>`<span><i style="background:${colors[i%colors.length]}"></i>${COUNTRY[f.id].name}</span>`).join('')}</div></figure>`;
}
export function campaignSummary(s,{country=s.player,tab='overview'}={}){
 const factions=Object.values(s.factions).sort((a,b)=>b.score-a.score),stats=s.campaignStats||{partial:true,factions:{}},recorded=stats.factions[country]||{},rows=Object.entries(ACTIONS).filter(([k,a])=>!a.disabled||recorded[k]).map(([k])=>[k,{...emptyRow(),...recorded[k]}]);
 const byStat=STAT_NAMES.map((name,i)=>{const items=rows.filter(([k])=>!ACTIONS[k].safe&&ACTIONS[k].stat===i);return {name,...items.reduce((a,[,v])=>{for(const k of ['success','failed','stopped','cost','chance','rolls'])a[k]+=v[k];return a;},{success:0,failed:0,stopped:0,cost:0,chance:0,rolls:0})};});
 const ranking=factions.map(f=>{const c=contributionBreakdown(s,f.id),v=operationTotals(s,f.id);return [COUNTRY[f.id].name+(f.id===s.player?' · Vous':''),cell(formatScore(f.score),f.score),cell(formatScore(c.protection),c.protection),c.defended,s.suspects.filter(t=>t.arrestedBy===f.id).length,v.count,v.cost,cell(pct(v.rolls?Math.round(v.randomSuccess/v.rolls*100):null),v.rolls?v.randomSuccess/v.rolls:-1)];});
 const own=contributionBreakdown(s,country),sum=own.protection+own.proofs+own.arrests+own.other,parts=[['Protection',own.protection],['Preuves',own.proofs],['Arrestations',own.arrests],['Autres / antérieur',own.other]];let angle=0;const stops=parts.map(([,v],i)=>{const start=angle;angle+=sum?v/sum*100:0;return `${colors[i]} ${start}% ${angle}%`;}).join(',');
 const operations=dataTable(['Action','Réussies / terminées','Interrompues','Réussite','Chance prévue moyenne','Crédits','Fatigue nette'],rows.sort((a,b)=>b[1].count-a[1].count).map(([k,v])=>[ACTIONS[k].name,cell(`${v.success} / ${v.success+v.failed}`,v.success),v.stopped,cell(ACTIONS[k].safe?'Automatique':pct(rate(v)),rate(v)??-1),cell(v.rolls?Math.round(v.chance/v.rolls)+' %':'—',v.rolls?v.chance/v.rolls:-1),v.cost,v.fatigue]),'Analyse de vos opérations');
 return `<section class="campaign-analysis"><nav class="report-tabs" aria-label="Sections du bilan">${[['overview','Vue globale'],['operations','Opérations'],['agents','Agents'],['support','Modules & gouvernement'],['cases','Enquêtes'],['timeline','Chronologie']].map(([id,name])=>`<button data-report-tab="${id}" aria-pressed="${tab===id}">${name}</button>`).join('')}</nav><div class="report-toolbar"><label>Pays analysé <select id="report-country">${factions.map(f=>`<option value="${f.id}" ${f.id===country?'selected':''}>${COUNTRY[f.id].name}${f.id===s.player?' · Vous':''}</option>`).join('')}</select></label><p>${stats.partial||stats.detailsPartial?'Historique partiel de cette ancienne sauvegarde.':'Suivi depuis le début de la campagne.'} Cliquez sur les colonnes pour trier.</p></div>
 <div data-report-panel="overview" ${tab!=='overview'?'hidden':''}><h2>Classement des pays · prestige et arrestations</h2>${dataTable(['Pays','Prestige','Points de protection','Attaques déjouées','Arrestations','Missions terminées','Crédits dépensés','Réussite avec jet'],ranking,'Comparaison de toutes les puissances')}<p class="muted">Protection : 6 points partagés entre les défenseurs de chaque attaque. Une protection sans attaque ne rapporte aucun prestige. ${s.ended==='defeat'?'Défaite collective : ce classement mesure les contributions, aucun pays ne gagne.':''}</p><div class="report-visuals">${prestigeChart(s,factions)}<figure class="report-chart contribution-chart"><figcaption>Origine du prestige · ${COUNTRY[country].name}</figcaption><div class="contribution-donut" style="background:${sum?'conic-gradient('+stops+')':'#343039'}" role="img" aria-label="${esc(parts.map(([k,v])=>k+': '+formatScore(v)).join(', '))}"><span>${formatScore(sum)}<small>points suivis</small></span></div><div class="contribution-key">${parts.map(([name,n],i)=>`<span><i style="background:${colors[i]}"></i>${name}<b>${formatScore(n)}</b></span>`).join('')}</div></figure></div><h2>Chance prévue vs réussite réelle</h2><div class="chance-comparison">${factions.map((f,i)=>{const v=operationTotals(s,f.id),expected=v.rolls?v.chance/v.rolls:0,actual=v.rolls?v.randomSuccess/v.rolls*100:0;return `<div><strong>${COUNTRY[f.id].name}</strong><small>${v.rolls} tentative(s) avec jet</small><div class="compare-bar"><span style="width:${expected}%;background:#847481"></span><b>Prévue ${v.rolls?Math.round(expected)+' %':'—'}</b></div><div class="compare-bar"><span style="width:${actual}%;background:${colors[i]}"></span><b>Réelle ${v.rolls?Math.round(actual)+' %':'—'}</b></div></div>`;}).join('')}</div></div>
 <div data-report-panel="operations" ${tab!=='operations'?'hidden':''}><h2>Analyse des opérations · ${COUNTRY[country].name}</h2>${operations}<h2>Résultats par capacité mobilisée</h2>${dataTable(['Capacité','Tentatives','Réussite observée','Chance prévue'],byStat.map(v=>[v.name,v.success+v.failed,cell(pct(rate(v)),rate(v)??-1),cell(v.rolls?Math.round(v.chance/v.rolls)+' %':'—',v.rolls?v.chance/v.rolls:-1)]))}<p class="muted">Les actions automatiques sont exclues de la comparaison des capacités. La chance prévue est celle enregistrée pour la mission. Les missions en cours et annulées sont exclues ; la fatigue nette inclut la récupération. Un petit échantillon ne mesure pas à lui seul l’efficacité d’une capacité.</p></div>
 <div data-report-panel="agents" ${tab!=='agents'?'hidden':''}>${agentPanel(s,country)}</div>
 <div data-report-panel="support" ${tab!=='support'?'hidden':''}>${supportPanel(s,country)}</div>
 <div data-report-panel="cases" ${tab!=='cases'?'hidden':''}><h2>Progression par enquête</h2><p>20 % par étape propre au pays : accès local, 2 preuves, au moins 1 vérifiée, préparation avec position valide et interpellation par ce pays. Ce pourcentage compare les dossiers ; il ne mesure pas la chance d’arrestation.</p>${dataTable(['Enquête',...factions.map(f=>COUNTRY[f.id].name),'Issue collective'],s.suspects.map(t=>[t.name,...factions.map(f=>{const n=investigationProgress(s,f.id,t);return {value:n,html:`<span class="case-percent">${n} %</span><progress max="100" value="${n}" aria-label="${esc(t.name+' · '+COUNTRY[f.id].name)}"></progress>`};}),t.arrested?'Arrêté'+(t.arrestedBy?' · '+COUNTRY[t.arrestedBy].name:''):'Non arrêté']),'Avancement des enquêtes par pays')}</div>
 <div data-report-panel="timeline" ${tab!=='timeline'?'hidden':''}>${horizontalTimeline(s,factions)}</div></section>`;
}

export function horizontalTimeline(s,factions){
 const turns=Math.max(1,s.turn),ledger=s.prestigeLedger||[],highlights=s.campaignStats?.highlights||[];
 return `<h2>Chronologie des équipes</h2><p class="muted">Une colonne par tour · hauteur = prestige gagné · ◆ arrestation · ⛨ protection · ★ réussite à 50 % ou moins · ★★ à 25 % ou moins. Survolez ou sélectionnez un tour pour lire les opérations et leurs agents.</p><div class="timeline-filters">${factions.map((f,i)=>`<label style="--team-color:${colors[i%colors.length]}"><input type="checkbox" data-timeline-toggle="${f.id}" checked><i></i>${esc(COUNTRY[f.id].name)}</label>`).join('')}</div><div class="compact-timeline" style="--turns:${turns}"><div class="compact-timeline-axis"><strong>Équipe / tour</strong>${Array.from({length:turns},(_,i)=>`<span>${i+1}</span>`).join('')}</div>${factions.map((f,i)=>`<section class="compact-timeline-team" data-timeline-team="${f.id}" style="--team-color:${colors[i%colors.length]}"><h3>${esc(COUNTRY[f.id].name)}<small>${formatScore(f.score)} pts</small></h3>${Array.from({length:turns},(_,j)=>{const turn=j+1,points=ledger.filter(e=>e.faction===f.id&&e.turn===turn),events=[...(s.campaignStats?.events||[]),...highlights.filter(h=>!(s.campaignStats?.events||[]).some(e=>e.turn===h.turn&&e.faction===h.faction&&e.agent===h.agent&&e.type===h.type))].filter(e=>e.faction===f.id&&e.turn===turn),gain=points.reduce((n,e)=>n+e.points,0),symbol=events.some(e=>successStars({...e,status:e.status||'RÉUSSITE'})==='★★')?'★★':events.some(e=>successStars({...e,status:e.status||'RÉUSSITE'}))?'★':events.some(e=>e.type==='arrest'&&(!e.status||e.status==='RÉUSSITE'))?'◆':points.some(e=>e.reason.startsWith('attentat déjoué'))?'⛨':'',detail=[...points.map(e=>'+'+formatScore(e.points)+' · '+e.reason),...events.map(e=>(e.chance<=25&&(!e.status||e.status==='RÉUSSITE')?'Exploit · ':'')+e.agent+' · '+ACTIONS[e.type].name+' · '+e.chance+' %')].join(' • ');return `<button class="timeline-mark ${gain||events.length?'has-event':''}" data-timeline-detail="${esc(detail||'Aucun événement marquant.') }" data-timeline-label="${esc(COUNTRY[f.id].name+' · Tour '+turn)}" aria-label="${esc(COUNTRY[f.id].name+' · T'+turn+' · '+(detail||'Aucun événement marquant'))}" data-rich-tooltip aria-haspopup="false"><i style="height:${Math.min(100,gain*8)}%"></i><b>${symbol|| (gain?formatScore(gain):'·')}</b><template>${timelineTooltip(s,f.id,turn,points,events)}</template></button>`;}).join('')}</section>`).join('')}</div><div id="timeline-detail" class="timeline-detail" aria-live="polite">Sélectionnez un tour pour consulter ses événements.</div>`;
}

export function recordAgentCondition(s,turn,missingOnly=false){
 const stats=s.campaignStats??={partial:true,factions:{}};
 for(const a of s.agents){const roster=(stats.agents??={})[a.faction]??={},record=roster[a.id]??={name:a.name,role:a.role||'',templateId:a.templateId||a.id,actions:{}};
 const history=record.conditionHistory??=[];
 if(missingOnly&&history.length||['dead','retired'].includes(a.status)&&history.at(-1)?.status===a.status)continue;
 const event=(s.campaignStats.events||[]).findLast(e=>e.agentId===a.id&&e.faction===a.faction&&e.turn===turn);
 const point={turn,energy:100-a.fatigue,exposure:a.exposure,status:a.status,...(turn?{action:event?.type||a.task?.type||null,result:event?.status||(a.task?'EN COURS':a.status==='captured'?'EN DÉTENTION':'SANS ORDRE'),chance:event?.chance??null}:{})};
 if(history.at(-1)?.turn===turn)history[history.length-1]=point;else history.push(point);
 }
}
export function successStars(e){return e&&e.status==='RÉUSSITE'&&!ACTIONS[e.type]?.safe&&Number.isFinite(e.chance)?e.chance<=25?'★★':e.chance<=50?'★':'':'';}
function conditionAction(s,country,id,p){if(!p.turn)return '';const e=(s.campaignStats?.events||[]).find(e=>e.agentId===id&&e.faction===country&&e.turn===p.turn);const type=e?.type||p.action,status=e?.status||p.result;return `<p><strong>${esc(ACTIONS[type]?.name||(status==='SANS ORDRE'?'Sans ordre':'Action non enregistrée'))}</strong></p><p>${esc(status||'Résultat non enregistré')} ${successStars(e||{type,status,chance:p.chance})}${type&&!ACTIONS[type]?.safe&&Number.isFinite(e?.chance??p.chance)?' · '+(e?.chance??p.chance)+' %':''}</p>`;}
export function agentConditionChart(s,country,id){
 const h=s.campaignStats?.agents?.[country]?.[id]?.conditionHistory||[];
 if(!h.length)return '<figure class="report-chart agent-condition-chart"><figcaption>Énergie & exposition</figcaption><p class="muted">Historique indisponible pour cette ancienne campagne.</p></figure>';
 const turns=Math.max(1,s.turn),max=Math.max(100,...h.map(p=>p.exposure)),x=t=>42+t/turns*680,y=n=>142-n/max*112;
 return `<figure class="report-chart agent-condition-chart"><figcaption>Énergie & exposition <small>${h[0].turn===0?'Départ, puis état en fin de tour':'Historique disponible à partir du tour '+h[0].turn}</small></figcaption><svg viewBox="0 0 750 177" role="img" aria-label="Progression de l’énergie et de l’exposition de l’agent au fil des tours">${[0,50,100,...(max>100?[max]:[])].map(n=>`<path d="M42 ${y(n)}H722" class="chart-grid"/><text x="7" y="${y(n)+4}">${n}</text>`).join('')}${[['energy','#8fd9c2'],['exposure','#efa0ae']].map(([key,color])=>`<path d="${h.map((p,i)=>`${i?'L':'M'}${x(p.turn)} ${y(p[key])}`).join(' ')}" fill="none" stroke="${color}" stroke-width="2.5"/>`).join('')}${h.map(p=>`<g tabindex="0" data-rich-tooltip aria-label="Tour ${p.turn}, énergie ${p.energy}, exposition ${p.exposure}"><rect x="${x(p.turn)-7}" y="20" width="14" height="125" fill="transparent"/><circle cx="${x(p.turn)}" cy="${y(p.energy)}" r="3" fill="#8fd9c2"/><circle cx="${x(p.turn)}" cy="${y(p.exposure)}" r="3" fill="#efa0ae"/><foreignObject width="0" height="0"><template><span class="eyebrow">${p.turn?'FIN DU TOUR '+p.turn:'DÉPART'}</span><h3>Énergie ${p.energy} / 100</h3><p>Exposition ${p.exposure}</p>${conditionAction(s,country,id,p)}</template></foreignObject></g>`).join('')}<text x="42" y="169">Départ</text><text x="678" y="169">Tour ${turns}</text></svg><div class="chart-legend"><span><i style="background:#8fd9c2"></i>Énergie</span><span><i style="background:#efa0ae"></i>Exposition</span></div></figure>`;
}
function timelineTooltip(s,faction,turn,points,events){return `<span class="eyebrow">${esc(COUNTRY[faction].name)} · TOUR ${turn}</span><h3>${points.length?'+'+formatScore(points.reduce((n,e)=>n+e.points,0))+' prestige':'Journal des opérations'}</h3>${events.map(e=>{const a=s.agents.find(a=>a.id===e.agentId||a.faction===faction&&a.name===e.agent)||{id:e.templateId,name:e.agent};return `<article class="timeline-tooltip-event">${e.agent?portrait(a):''}<div><strong>${esc(e.agent||'Équipe')}</strong><p>${esc(ACTIONS[e.type]?.name||e.type)}</p><small>${esc(e.status||'RÉUSSITE')} ${successStars({...e,status:e.status||'RÉUSSITE'})} · ${ACTIONS[e.type]?.safe?'Automatique':e.chance+' %'}${COUNTRY[e.country]?' · '+esc(COUNTRY[e.country].name):''}</small>${e.targetName?`<p>Cible : ${esc(e.targetName)}</p>`:''}</div></article>`;}).join('')}${points.map(e=>`<p class="tooltip-prestige">+${formatScore(e.points)} · ${esc(e.reason)}</p>`).join('')}${!points.length&&!events.length?'<p>Aucun événement enregistré pour ce tour.</p>':''}`;}
